import ipaddr from 'ipaddr.js';
import type { Detection } from './types.ts';
import { fold, searchIndex, reconcileLabelledFields, type LabelledFields } from './labelled-fields.ts';

const horizontal = '[^\\S\\r\\n]';
const fieldLabels = new RegExp(`(?<![a-z0-9_])(ngay sinh|sinh ngay|date of birth|dob|ngay giao dich|ngay hach toan|ngay hen(?: tra ket qua)?|phien ban(?: phan mem)?|version|ma http|http status|so ho so da xu ly|tong so chung tu)(?![a-z0-9_])`, 'g');
const datePrefix = new RegExp(`^(?:ngay${horizontal}+)?(\\d{1,2})${horizontal}+thang${horizontal}+(\\d{1,2})${horizontal}+nam${horizontal}+(\\d{4})(?![a-z0-9_/])`);
const numericDate = /^(\d{1,2})\/(\d{1,2})\/(\d{4})(?![a-z0-9_/])/;
const legalPrefix = /(?<![a-z0-9_])(?:cong ty(?: (?:tnhh|co phan|trach nhiem huu han))?|hop tac xa|doanh nghiep tu nhan)(?![a-z0-9_])/g;
